/**
 * The Wool Buyers' Ring — structural test generated by compile:encounter (THR-1246).
 * Expected values are baked from the content package, so this file asserts the
 * encounter's actual shape rather than any template's.
 */

import { describe, expect, it } from 'vitest';
import { WOOL_STAPLE_TEMPLATE } from '../wool-staple';
import { expandSettings } from '../../settingClasses';
import { drawConsequenceHand, handAfterSwap } from '../../content-eval/consequenceDraw';

describe("The Wool Buyers' Ring — template structure", () => {
  it('carries its identity', () => {
    expect(WOOL_STAPLE_TEMPLATE.id).toBe('encounter.town.wool_staple');
    expect(WOOL_STAPLE_TEMPLATE.reach).toBe('gold');
    expect(WOOL_STAPLE_TEMPLATE.rarityTier).toBe(2);
    expect(WOOL_STAPLE_TEMPLATE.steps).toHaveLength(2);
  });

  it('step 0 deals the authored hand', () => {
    const step = WOOL_STAPLE_TEMPLATE.steps[0];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['wool.stir_suspicion', 'wool.dull_the_factor']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['entropy', 'mind']);
  });

  it('step 1 deals the authored hand', () => {
    const step = WOOL_STAPLE_TEMPLATE.steps[1];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['wool.clean_the_fleece', 'wool.steady_the_scales']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['life', 'matter']);
  });
  it('derives its location subtypes from the declared envelope', () => {
    expect(WOOL_STAPLE_TEMPLATE.settings).toEqual(['urban']);
    expect(WOOL_STAPLE_TEMPLATE.locationSubtypes).toEqual(expandSettings(['urban']));
  });

  it('records exactly the hand its id draws (binding, THR-1145)', () => {
    expect(WOOL_STAPLE_TEMPLATE.consequenceDraw).toEqual(['possession', 'story_seed']);
    expect(WOOL_STAPLE_TEMPLATE.consequenceDraw).toEqual(
      handAfterSwap(
        drawConsequenceHand({
          templateId: 'encounter.town.wool_staple',
          reach: 'gold',
          rarityTier: 2,
        }),
        WOOL_STAPLE_TEMPLATE.consequenceSwap,
      ),
    );
  });
});
